function interviewsPage(){return head('INTERVIEWS & CONVERSATIONS','采访与对谈','从采访、对谈与公开问答中，了解王安忆的创作思考。')+'<div class="toolbar"><input id="interviewSearch" type="search" aria-label="搜索采访与对谈" placeholder="搜索标题、采访者、作品或主题"><select id="interviewFormat" aria-label="按采访形式筛选"><option>全部形式</option><option>文字</option><option>音频</option></select><select id="interviewSort" aria-label="按采访日期排序"><option value="desc">由近到远</option><option value="asc">由远到近</option></select></div><p id="interviewCount" class="source" aria-live="polite"></p><div id="interviewList" class="interview-list"></div><section class="section"><h2>收录说明</h2><p class="source">本栏目资料由项目发起者从网络搜集整理，力求全面收录，仍可能存在遗漏。日期为所链接网页的发布日期，已知访谈或活动日期另列。同次访谈的转载与节选尽量合并，全文及音频请访问来源网站。</p></section>'}
function renderInterviews(){const q=document.querySelector('#interviewSearch').value.trim().toLocaleLowerCase(),format=document.querySelector('#interviewFormat').value,sort=document.querySelector('#interviewSort').value;const list=interviewRecords.filter(r=>(format==='全部形式'||!format||format===r.format)&&[r.title,r.interviewer,r.source,r.topics,r.date,r.eventDate].join(' ').toLocaleLowerCase().includes(q)).sort((a,b)=>sort==='asc'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));document.querySelector('#interviewCount').textContent='显示 '+list.length+' 项采访与对谈';document.querySelector('#interviewList').innerHTML=list.length?list.map(r=>'<article class="interview-item"><div class="interview-date"><time datetime="'+r.date+'">'+r.date+'</time><span>'+esc(r.format)+' · '+esc(r.kind)+'</span></div><div><h2><a href="'+esc(r.url)+'" target="_blank" rel="noopener">'+esc(r.title)+' ↗</a></h2><p class="source">采访／对谈者：'+esc(r.interviewer)+'<br>来源：'+esc(r.source)+(r.eventDate?'<br>访谈／活动时间：'+esc(r.eventDate):'')+'</p><p class="interview-topics">'+esc(r.topics)+'</p>'+(r.notes?'<p class="source">'+esc(r.notes)+'</p>':'')+'</div></article>').join(''):'<p class="empty">暂无匹配采访，请调整关键词或形式。</p>'}

render();
